use crate::api::client::ApiClient;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use std::collections::BTreeMap;

const BILLING_INTERVAL_SECONDS: i64 = 15 * 60;

pub struct InvoiceMonthlyCommand;

impl InvoiceMonthlyCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client.get_time_entries_filtered(since, until).await?;
        let monthly = monthly_billable_seconds(&entries);

        if monthly.is_empty() {
            println!("(no data)");
            return Ok(());
        }

        let total: i64 = monthly.values().sum();
        for (month, seconds) in monthly {
            println!("{month}  {seconds}s");
        }
        println!("Total  {total}s");
        Ok(())
    }
}

fn monthly_billable_seconds(entries: &[TimeEntry]) -> BTreeMap<String, i64> {
    let mut monthly = BTreeMap::new();
    for entry in entries {
        if !entry.billable || entry.stop.is_none() || entry.duration < 0 {
            continue;
        }

        let billed_seconds = ((entry.duration + BILLING_INTERVAL_SECONDS - 1)
            / BILLING_INTERVAL_SECONDS)
            * BILLING_INTERVAL_SECONDS;
        let month = entry.start.format("%Y-%m").to_string();
        *monthly.entry(month).or_insert(0) += billed_seconds;
    }
    monthly
}

#[cfg(test)]
mod tests {
    use super::*;
    use chrono::{TimeZone, Utc};

    fn entry(start: &str, duration: i64, billable: bool, stopped: bool) -> TimeEntry {
        let start = Utc.datetime_from_str(start, "%Y-%m-%dT%H:%M:%SZ").unwrap();
        TimeEntry {
            start,
            duration,
            billable,
            stop: stopped.then_some(start),
            ..TimeEntry::default()
        }
    }

    #[test]
    fn groups_completed_billable_entries_by_utc_start_month() {
        let entries = vec![
            entry("2024-02-01T00:00:00Z", 901, true, true),
            entry("2024-01-31T23:30:00Z", 60, true, true),
            entry("2024-02-15T00:00:00Z", 1, false, true),
            entry("2024-02-20T00:00:00Z", 60, true, false),
        ];

        assert_eq!(
            monthly_billable_seconds(&entries)
                .into_iter()
                .collect::<Vec<_>>(),
            vec![("2024-01".to_string(), 900), ("2024-02".to_string(), 1_800)]
        );
    }

    #[test]
    fn empty_when_no_completed_billable_entries() {
        assert!(monthly_billable_seconds(&[]).is_empty());
    }
}
